class ArrayStack:
    def __init__(self):
        self._data = [None] * 100
        self.topo = -1  # pilha vazia

    def is_empty(self):
        return self.topo == -1

    def push(self, e):
        if self.topo >= 99:
            return
        self.topo += 1
        self._data[self.topo] = e

    def top(self):
        if self.is_empty():
            print('pilha vazia')
            return None
        else:
            return self._data[self.topo]

    def pop(self):
        if self.is_empty():
            print('pilha vazia')
            return None
        else:
            elem = self._data[self.topo]
            self.topo -= 1
            return elem

